// Step 0: read what the client chose on the first form
const f = $input.first().json;
const email = String(f['Email'] || '').trim().toLowerCase();
const choice = String(f['What would you like to do?'] || '').trim();
const action = choice.startsWith('Book') ? 'new' : choice.startsWith('Change') ? 'change' : choice.startsWith('Cancel') ? 'cancel' : '';
let message = '';
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) message = 'The email address is not valid. Please open the form again and check it.';
else if (!action) message = 'Please choose what you would like to do. Open the form again and try once more.';
return [{ json: { email, action, ok: message === '', title: 'Please check your details', message } }];

// Reads the whole Bookings sheet, finds this client's upcoming bookings and decides where to go next
const cfg = $('Config').first().json;
const req = $('Read Request').first().json;
const zone = cfg.timezone;
const now = DateTime.now().setZone(zone);
const minChange = Number(cfg.minChangeHours) || 0;
const maxActive = Number(cfg.maxActiveBookings) || 3;
const errText = e => typeof e === 'string' ? e : ((e && (e.message || e.description)) || JSON.stringify(e || ''));
const pad = n => String(n).padStart(2, '0');
// The sheet keeps dates and times as text. If someone retypes a cell, Google may turn it into a number: handle both.
const dStr = v => {
  if (typeof v === 'number') return DateTime.fromMillis(Date.UTC(1899, 11, 30) + Math.round(v) * 86400000, { zone: 'utc' }).toFormat('yyyy-MM-dd');
  const s = String(v == null ? '' : v).trim();
  const m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  return m ? `${m[1]}-${pad(m[2])}-${pad(m[3])}` : s;
};
const tStr = v => {
  if (typeof v === 'number') { const mins = Math.round((v % 1) * 1440); return `${pad(Math.floor(mins / 60) % 24)}:${pad(mins % 60)}`; }
  const s = String(v == null ? '' : v).trim();
  const m = s.match(/^(\d{1,2}):(\d{2})/);
  return m ? `${pad(m[1])}:${m[2]}` : s;
};

const items = $input.all().map(i => i.json);
const readError = items.find(r => r && r.error);
const hasRows = items.some(r => r && r.row_number !== undefined);
const headerBroken = hasRows && !items.some(r => r && r['Booking ID'] !== undefined && r['Email'] !== undefined && r['Status'] !== undefined);
const lookupFailed = !!readError || headerBroken;
const lookupError = readError ? errText(readError.error) : (headerBroken ? 'The header row of the Bookings sheet was changed.' : '');
const rows = items.filter(r => r && r['Booking ID'] !== undefined && String(r['Booking ID']).trim() !== '');
const existingIds = rows.map(r => String(r['Booking ID']).trim());

const mine = rows.map(r => {
  const date = dStr(r['Date']);
  const time = tStr(r['Start Time']);
  return { r, date, time, start: DateTime.fromFormat(`${date} ${time}`, 'yyyy-MM-dd HH:mm', { zone }) };
}).filter(x => String(x.r['Email'] || '').trim().toLowerCase() === req.email
  && String(x.r['Status'] || '').trim().toLowerCase() === 'booked'
  && x.start.isValid && x.start > now)
  .sort((a, b) => a.start.toMillis() - b.start.toMillis())
  .map(x => {
    const id = String(x.r['Booking ID']).trim();
    const service = String(x.r['Service'] || '').trim();
    return {
      bookingId: id, service,
      name: String(x.r['Client Name'] || '').trim(), phone: String(x.r['Phone'] || '').trim(),
      notes: String(x.r['Notes'] || '').trim(), eventId: String(x.r['Calendar Event ID'] || '').trim(),
      durationMin: Number(x.r['Duration (min)']) || 0, changedCount: Number(x.r['Changed Count']) || 0,
      date: x.date, time: x.time, startISO: x.start.toISO(),
      whenText: x.start.toFormat("cccc, d LLLL yyyy 'at' HH:mm"),
      hoursAway: x.start.diff(now, 'hours').hours,
      label: `${id} | ${service} | ${x.start.toFormat("ccc, d LLL yyyy 'at' HH:mm")}`
    };
  });
const changeable = mine.filter(b => b.hoursAway >= minChange);

let route = req.action;
let title = '';
let message = '';
if (lookupFailed && req.action !== 'new') {
  route = 'error';
  title = 'Technical problem';
  message = 'We could not read our bookings right now. Nothing was changed. Please try again in a few minutes or contact us directly.';
} else if (!lookupFailed) {
  if (req.action === 'new' && mine.length >= maxActive) {
    route = 'blocked'; title = 'Booking limit reached';
    message = `You already have ${mine.length} upcoming bookings, which is the maximum. Please change or cancel one first.`;
  } else if (req.action !== 'new' && mine.length === 0) {
    route = 'blocked'; title = 'No booking found';
    message = `We could not find an upcoming booking for ${req.email}. Please check the email address you used when you booked, or choose "Book a new appointment".`;
  } else if (req.action !== 'new' && changeable.length === 0) {
    route = 'blocked'; title = 'Please contact us';
    message = `Your next booking (${mine[0].whenText}) starts in less than ${minChange} hours, so it cannot be changed or canceled online. Please contact us directly and we will help you.`;
  }
}
return [{ json: { ...req, route, title, message, lookupFailed, lookupError, activeCount: mine.length, bookings: mine, changeable, existingIds } }];

