// Builds the step-1 form from the Services sheet (new booking or change booking)
const cfg = $('Config').first().json;
const pb = $('Process Bookings').first().json;
const mode = pb.action;
const items = $input.all().map(i => i.json);
const readError = items.find(r => r && r.error);
const off = v => ['no', 'n', 'false', '0', 'inactive'].includes(String(v == null ? '' : v).trim().toLowerCase());
const seen = new Set();
const services = [];
for (const r of items) {
  if (!r || r['Service Name'] === undefined) continue;
  const name = String(r['Service Name']).trim();
  if (!name || seen.has(name) || off(r['Active'])) continue;
  seen.add(name);
  services.push({ name, duration: Math.round(Number(r['Duration (min)'])) || Number(cfg.defaultDurationMin) || 60 });
}
const keepText = mode === 'change' ? ' Your current booking was not changed.' : '';
let title = 'Technical problem';
let message = '';
if (readError) message = 'We could not read our services list right now. Please try again in a few minutes.' + keepText;
else if (!services.length) { title = 'No services available'; message = 'There are no services open for booking at the moment. Please contact us directly.' + keepText; }

const KEEP = 'Keep my current service';
const svcOptions = services.map(s => ({ option: s.name }));
let fields;
if (mode === 'change') {
  fields = [
    { fieldLabel: 'Which booking do you want to change?', fieldType: 'dropdown', requiredField: true, fieldOptions: { values: (pb.changeable || []).map(b => ({ option: b.label })) } },
    { fieldLabel: 'Service', fieldType: 'dropdown', requiredField: true, fieldOptions: { values: [{ option: KEEP }, ...svcOptions] } },
    { fieldLabel: 'New date', fieldType: 'date', requiredField: true }
  ];
} else {
  fields = [
    { fieldLabel: 'Service', fieldType: 'dropdown', requiredField: true, fieldOptions: { values: svcOptions } },
    { fieldLabel: 'Preferred date', fieldType: 'date', requiredField: true }
  ];
}
return [{ json: {
  ok: message === '', title, message, mode, services,
  formTitle: mode === 'change' ? 'Change Your Appointment' : 'Book Your Appointment',
  formDescription: mode === 'change'
    ? 'Step 1 of 2 · Choose the booking, the service and the new date. Next, you will see the free times.'
    : 'Step 1 of 2 · Choose your service and preferred date. Next, you will see the free times.',
  formJson: JSON.stringify(fields)
} }];

