parameters.jsCode:
// Checks the choices of step 1 and prepares the day window for the calendar
const cfg = $('Config').first().json;
const pb = $('Process Bookings').first().json;
const sf = $('Build Service Form').first().json;
const f = $input.first().json;
const zone = cfg.timezone;
const mode = pb.action;
const KEEP = 'Keep my current service';
const now = DateTime.now().setZone(zone);
const date = String(f[mode === 'change' ? 'New date' : 'Preferred date'] || '').trim();
const day = DateTime.fromISO(date, { zone });
const closed = String(cfg.closedWeekdays == null ? '' : cfg.closedWeekdays).split(',').map(x => parseInt(x, 10)).filter(x => x >= 1 && x <= 7);
const maxDays = Number(cfg.maxDaysAhead) || 60;

let booking = null;
let problem = '';
if (mode === 'change') {
  const id = String(f['Which booking do you want to change?'] || '').split(' | ')[0].trim();
  booking = (pb.changeable || []).find(b => b.bookingId === id) || null;
  if (!booking) problem = 'We could not find the booking you selected.';
  else if (DateTime.fromISO(booking.startISO).diff(now, 'hours').hours < (Number(cfg.minChangeHours) || 0)) problem = 'This booking starts very soon, so it cannot be changed online. Please contact us directly.';
}
const choice = String(f['Service'] || '').trim();
const keepService = mode === 'change' && choice === KEEP && !!booking;
const serviceName = keepService ? booking.service : choice;
const found = (sf.services || []).find(s => s.name === serviceName);
if (!problem && !found && !keepService) problem = 'This service is not available any more.';
if (!problem) {
  if (!date || !day.isValid) problem = 'The date is not valid.';
  else if (day.endOf('day') < now) problem = 'This date is in the past.';
  else if (day.startOf('day') > now.plus({ days: maxDays })) problem = `We only take bookings up to ${maxDays} days ahead.`;
  else if (closed.includes(day.weekday)) problem = 'We are closed on this day.';
}
const durationMin = found ? found.duration : ((booking && booking.durationMin) || Number(cfg.defaultDurationMin) || 60);
const start = day.isValid ? day.startOf('day') : now.startOf('day');
const keepText = mode === 'change' ? ' Your current booking was not changed.' : '';
return [{ json: {
  ok: problem === '', title: 'Please check your choice',
  message: problem ? `${problem}${keepText} Please open the form again and try once more.` : '',
  mode, email: pb.email, date, serviceName, durationMin, booking,
  timeMin: start.toISO(), timeMax: start.plus({ days: 1 }).toISO()
} }];

// Finds the free times of the chosen day and builds the step-2 form
const cfg = $('Config').first().json;
const w = $('Day Window').first().json;
const zone = cfg.timezone;
const items = $input.all().map(i => i.json);
const calendarError = items.some(b => b && b.error);
const val = x => (x && typeof x === 'object') ? (x.dateTime || x.date) : x;
const busy = items.filter(b => b && b.start && b.end)
  .map(b => ({ s: DateTime.fromISO(val(b.start)), e: DateTime.fromISO(val(b.end)) }))
  .filter(b => b.s.isValid && b.e.isValid);
const keepText = w.mode === 'change' ? ' Your current booking was not changed.' : '';
const dur = Number(w.durationMin) || Number(cfg.defaultDurationMin) || 60;
const step = Number(cfg.slotStepMin) || 30;
const workStart = Number(cfg.workStart);
const workEnd = Number(cfg.workEnd);

let problem = '';
if (calendarError) problem = 'We could not read our calendar right now. Please try again in a few minutes.';
const free = [];
if (!problem) {
  const day = DateTime.fromISO(w.date, { zone });
  const earliest = DateTime.now().setZone(zone).plus({ hours: Number(cfg.minNoticeHours) || 0 });
  for (let m = workStart * 60; m + dur <= workEnd * 60; m += step) {
    const s = day.startOf('day').plus({ minutes: m });
    const e = s.plus({ minutes: dur });
    const clash = busy.some(b => s < b.e && e > b.s);
    if (!clash && s > earliest) free.push(s.toFormat('HH:mm'));
  }
}
const fields = [{ fieldLabel: 'Available time', fieldType: 'dropdown', requiredField: true, fieldOptions: { values: free.map(t => ({ option: t })) } }];
if (w.mode === 'new') {   // a returning client that moves a booking is already known
  fields.push({ fieldLabel: 'Full name', placeholder: 'e.g. Ahmed Hassan', requiredField: true });
  fields.push({ fieldLabel: 'Phone', placeholder: '+20 1XX XXX XXXX', requiredField: true });
}
fields.push({ fieldLabel: 'Notes', fieldType: 'textarea', placeholder: 'Anything we should know? (optional)' });
const message = problem
  ? problem + keepText
  : (free.length ? '' : 'There are no free times on this day. Please open the form again and choose another date.' + keepText);
return [{ json: {
  hasFree: free.length > 0, title: problem ? 'Calendar problem' : 'No free time', message,
  mode: w.mode, date: w.date, durationMin: dur, freeCount: free.length,
  formTitle: w.mode === 'change' ? 'Choose Your New Time' : 'Choose Your Time',
  formDescription: `Step 2 of 2 · Free times on ${w.date} · ${dur} min`,
  buttonLabel: w.mode === 'change' ? 'Confirm New Time' : 'Confirm My Booking',
  formJson: JSON.stringify(fields)
} }];

