parameters.jsCode:
// Collects everything the sheet and the calendar need
const cfg = $('Config').first().json;
const zone = cfg.timezone;
const w = $('Day Window').first().json;
const pb = $('Process Bookings').first().json;
const f = $input.first().json;
const ex = w.mode === 'change' ? w.booking : null;
const reschedule = !!ex;
const clean = s => String(s || '').trim().replace(/\s+/g, ' ');

const email = w.email;
const name = reschedule ? (clean(ex.name) || email.split('@')[0]) : clean(f['Full name']);
const phone = reschedule ? String(ex.phone || '') : String(f['Phone'] || '').replace(/[^\d+]/g, '');
const time = String(f['Available time'] || '').trim();
const notes = String(f['Notes'] || '').trim() || (reschedule ? String(ex.notes || '') : '');
const dur = Number(w.durationMin) || Number(cfg.defaultDurationMin) || 60;

const errors = [];
if (!reschedule && name.length < 2) errors.push('Please enter your full name.');
if (!reschedule && phone.replace(/\D/g, '').length < 7) errors.push('The phone number looks too short.');
const now = DateTime.now().setZone(zone);
const start = DateTime.fromFormat(`${w.date} ${time}`, 'yyyy-MM-dd HH:mm', { zone });
if (!start.isValid) errors.push('The time is not valid.');
else if (start < now) errors.push('This time has already passed.');
const safeStart = start.isValid ? start : now;   // a dummy value keeps the next calendar check from crashing; "valid" stays false
const end = safeStart.plus({ minutes: dur });

const taken = new Set((pb.existingIds || []).map(String));
let bookingId = reschedule ? ex.bookingId : '';
for (let i = 0; !bookingId && i < 100; i++) {
  const c = 'BK-' + safeStart.toFormat('yyyyLLdd') + '-' + Math.floor(1000 + Math.random() * 9000);
  if (!taken.has(c)) bookingId = c;
}
if (!bookingId) bookingId = 'BK-' + Date.now();
const nowText = now.toFormat('yyyy-LL-dd HH:mm');
const parts = name.split(' ');
return [{ json: {
  BookingID: bookingId, mode: reschedule ? 'change' : 'new',
  Name: name, FirstName: parts[0] || '', LastName: parts.slice(1).join(' '),
  Email: email, Phone: phone, Service: w.serviceName,
  Date: w.date, Time: time, EndTime: end.toFormat('HH:mm'), DurationMin: dur, Notes: notes,
  Slot: `${w.date} ${time}`, startISO: safeStart.toISO(), endISO: end.toISO(),
  CreatedAt: nowText, UpdatedAt: nowText,
  ChangedCount: reschedule ? (ex.changedCount || 0) + 1 : 0,
  previousWhen: reschedule ? ex.whenText : '',
  existing: ex, valid: errors.length === 0, errors
} }];

// Last safety check: was this time taken while the client was filling the form?
const b = $('Prepare Booking').first().json;
const items = $input.all().map(i => i.json);
const calendarError = items.some(x => x && x.error);
const busy = items.filter(x => x && x.start && x.end);

let Status = 'Confirmed';
let Reason = '';
if (!b.valid) { Status = 'Rejected'; Reason = b.errors.join(' '); }
else if (calendarError) { Status = 'Rejected'; Reason = 'We could not check our calendar right now. Please try again in a few minutes.'; }
else if (busy.length > 0) { Status = 'Rejected'; Reason = 'Sorry, someone just booked this time. Please choose another time.'; }
if (Status === 'Rejected' && b.mode === 'change') Reason += ' Your current booking was not changed.';
return [{ json: { ...b, Status, Reason } }];

const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const THEMES = { blue: '#2563eb', green: '#16a34a', red: '#dc2626', amber: '#d97706' };
// rows = [[label, valueHtml], ...]   (valueHtml must already be escaped with esc())
function emailHtml(o) {
  const c = THEMES[o.theme || 'blue'];
  const rows = (o.rows || []).filter(r => r && r[1] !== '' && r[1] != null).map(r =>
    `<tr><td style="padding:9px 14px 9px 0;color:#64748b;font-size:13px;white-space:nowrap;vertical-align:top">${r[0]}</td><td style="padding:9px 0;color:#0f172a;font-size:15px;font-weight:600">${r[1]}</td></tr>`).join('');
  const box = rows ? `<tr><td style="padding:20px 32px 0"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:12px"><tr><td style="padding:8px 20px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0">${rows}</table></td></tr></table></td></tr>` : '';
  const btn = o.button ? `<tr><td style="padding:24px 32px 0"><a href="${esc(o.button.url)}" style="display:inline-block;background:${c};color:#ffffff;text-decoration:none;font-weight:600;font-size:15px;padding:13px 26px;border-radius:10px">${esc(o.button.label)}</a></td></tr>` : '';
  const note = o.note ? `<tr><td style="padding:20px 32px 0;font-size:13px;line-height:1.6;color:#64748b">${o.note}</td></tr>` : '';
  return `<div style="margin:0;padding:24px 12px;background:#eef2f7;font-family:Inter,'Segoe UI',Arial,Helvetica,sans-serif">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;margin:0 auto"><tr><td>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#ffffff;border:1px solid #e2e8f0;border-radius:16px;overflow:hidden">
<tr><td style="background:${c};height:6px;line-height:6px;font-size:0">&nbsp;</td></tr>
<tr><td style="padding:28px 32px 0"><div style="font-size:12px;font-weight:700;letter-spacing:.8px;text-transform:uppercase;color:${c}">${esc(o.business)}</div>
<h1 style="margin:10px 0 0;font-size:24px;line-height:1.3;color:#0f172a">${o.icon || ''} ${esc(o.title)}</h1></td></tr>
<tr><td style="padding:12px 32px 0;font-size:15px;line-height:1.7;color:#334155">${o.intro || ''}</td></tr>
${box}${btn}${note}
<tr><td style="padding:28px 32px"><div style="border-top:1px solid #e2e8f0;padding-top:16px;font-size:12px;color:#94a3b8">${esc(o.business)}</div></td></tr>
</table></td></tr></table></div>`;
}
const errText = e => typeof e === 'string' ? e : ((e && (e.message || e.description)) || JSON.stringify(e || ''));
const zone = $('Config').first().json.timezone;
const cfg = $('Config').first().json;
const b = $('Decide').first().json;
const pb = $('Process Bookings').first().json;
const resched = b.mode === 'change';
const start = DateTime.fromISO(b.startISO, { zone });
const dateText = start.toFormat('cccc, d LLLL yyyy');

const clientHtml = emailHtml({
  business: cfg.businessName, theme: resched ? 'blue' : 'green', icon: resched ? '🔄' : '✅',
  title: resched ? 'Booking updated' : 'Booking confirmed',
  intro: `Hi ${esc(b.FirstName)},<br>${resched ? 'Your booking has been moved. Here are the new details:' : 'Your booking is confirmed. Here are the details:'}`,
  rows: [['Booking ID', esc(b.BookingID)], ['Service', esc(b.Service)], ['Date', esc(dateText)], ['Time', esc(b.Time + ' (' + b.DurationMin + ' min)')],
         resched ? ['Previous time', esc(b.previousWhen)] : null],
  button: { label: 'Change or cancel my booking', url: cfg.formUrl },
  note: 'To change or cancel, open the booking form, choose "Change my appointment" or "Cancel my appointment", and enter the same email address you used for this booking.'
});

// anything that went wrong AFTER the booking was saved is a warning for the owner, not an error for the client
const warns = [];
if (resched) {
  if ($('Delete Old Event').isExecuted) {
    const d = $('Delete Old Event').first().json;
    if (d && d.error) warns.push('The old calendar event could not be deleted automatically. Please delete it by hand: ' + esc(b.previousWhen));
  }
} else if ($('Save Client').isExecuted) {
  const c = $('Save Client').first().json;
  if (c && c.error) warns.push('The booking was saved, but the Clients sheet could not be updated: ' + esc(String(errText(c.error)).slice(0, 200)));
}
if (pb.lookupFailed) warns.push('The duplicate-booking check was skipped because the Bookings sheet could not be read: ' + esc(String(pb.lookupError || '').slice(0, 200)));
const warnBox = warns.length ? `<div style="background:#fef2f2;border:1px solid #fecaca;color:#991b1b;border-radius:10px;padding:12px 14px">⚠️ ${warns.join('<br>⚠️ ')}</div>` : '';
const ownerHtml = emailHtml({
  business: cfg.businessName, theme: warns.length ? 'red' : (resched ? 'blue' : 'green'), icon: resched ? '🔄' : '📅',
  title: resched ? 'Booking moved' : 'New booking',
  intro: warnBox || (resched ? 'A client moved their booking.' : 'A client booked an appointment.'),
  rows: [['Booking ID', esc(b.BookingID)], ['Name', esc(b.Name)], ['Phone', esc(b.Phone)], ['Email', esc(b.Email)],
         ['Service', esc(b.Service)], ['When', esc(dateText + ' at ' + b.Time)],
         resched ? ['Previous time', esc(b.previousWhen)] : null,
         ['Notes', esc(b.Notes).replace(/\n/g, '<br>')]]
});
return [{ json: {
  clientSubject: `${resched ? 'Booking updated' : 'Booking confirmed'} - ${b.BookingID}`, clientHtml,
  ownerSubject: `${warns.length ? '⚠️ ' : ''}${resched ? 'Booking moved' : 'New booking'}: ${b.Name} - ${b.Slot}`, ownerHtml,
  screenWhen: `${dateText} at ${b.Time}`
} }];

