  const rows = (o.rows || []).filter(r => r && r[1] !== '' && r[1] != null).map(r =>
    `<tr><td style="padding:9px 14px 9px 0;color:#64748b;font-size:13px;white-space:nowrap;vertical-align:top">${r[0]}</td><td style="padding:9px 0;color:#0f172a;font-size:15px;font-weight:600">${r[1]}</td></tr>`).join('');
  const box = rows ? `<tr><td style="padding:20px 32px 0"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:12px"><tr><td style="padding:8px 20px"><table role="presentation" width="100%" cellpadding="0" cellspacing="0">${rows}</table></td></tr></table></td></tr>` : '';
  const btn = o.button ? `<tr><td style="padding:24px 32px 0"><a href="${esc(o.button.url)}" style="display:inline-block;background:${c};color:#ffffff;text-decoration:none;font-weight:600;font-size:15px;padding:13px 26px;border-radius:10px">${esc(o.button.label)}</a></td></tr>` : '';
  const note = o.note ? `<tr><td style="padding:20px 32px 0;font-size:13px;line-height:1.6;color:#64748b">${o.note}</td></tr>` : '';
  return `<div style="margin:0;padding:24px 12px;background:#eef2f7;font-family:Inter,'Segoe UI',Arial,Helvetica,sans-serif">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;margin:0 auto"><tr><td>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#ffffff;border:1px solid #e2e8f0;border-radius:16px;overflow:hidden">
<tr><td style="background:${c};height:6px;line-height:6px;font-size:0">&nbsp;</td></tr>
<tr><td style="padding:28px 32px 0"><div style="font-size:12px;font-weight:700;letter-spacing:.8px;text-transform:uppercase;color:${c}">${esc(o.business)}</div>
<h1 style="margin:10px 0 0;font-size:24px;line-height:1.3;color:#0f172a">${o.icon || ''} ${esc(o.title)}</h1></td></tr>
<tr><td style="padding:12px 32px 0;font-size:15px;line-height:1.7;color:#334155">${o.intro || ''}</td></tr>
${box}${btn}${note}
<tr><td style="padding:28px 32px"><div style="border-top:1px solid #e2e8f0;padding-top:16px;font-size:12px;color:#94a3b8">${esc(o.business)}</div></td></tr>
</table></td></tr></table></div>`;
}
const errText = e => typeof e === 'string' ? e : ((e && (e.message || e.description)) || JSON.stringify(e || ''));
const cfg = $('Config').first().json;
const d = $('Decide').first().json;
let reason = d.Reason;
for (const n of ['Calendar Failed', 'Sheet Failed']) {
  if ($(n).isExecuted) { try { reason = $(n).first().json.Reason || reason; } catch (e) {} }
}
const clientHtml = emailHtml({
  business: cfg.businessName, theme: 'red', icon: '⚠️', title: 'We could not confirm your booking',
  intro: `Hi ${esc(d.FirstName || 'there')},<br>${esc(reason)}`,
  button: { label: 'Try again', url: cfg.formUrl },
  note: 'Thank you for your patience.'
});
return [{ json: { to: d.Email, subject: 'We could not confirm your booking', clientHtml, reason } }];

