${box}${btn}${note}
<tr><td style="padding:28px 32px"><div style="border-top:1px solid #e2e8f0;padding-top:16px;font-size:12px;color:#94a3b8">${esc(o.business)}</div></td></tr>
</table></td></tr></table></div>`;
}
const errText = e => typeof e === 'string' ? e : ((e && (e.message || e.description)) || JSON.stringify(e || ''));
const cfg = $('Config').first().json;
const e = $('Resolve Cancel').first().json.booking;
const email = $('Process Bookings').first().json.email;
const err = errText($input.first().json.error);
return [{ json: {
  alertSubject: `⚠️ Cancel failed: ${email}`,
  alertHtml: emailHtml({ business: cfg.businessName, theme: 'red', icon: '⚠️', title: 'A client could not cancel online',
    intro: 'Google Sheets did not accept the status change, so nothing was canceled. The booking is still active. Please contact the client.',
    rows: [['Email', esc(email)], ['Booking ID', esc(e.bookingId)], ['When', esc(e.whenText)], ['Error', esc(String(err).slice(0, 300))]] })
} }];

